{"implementation":"def solve(case):
    nodes = list(case["nodes"])
    core_distance = case["core_distance"]

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        root = node
        while parent[root] != root:
            root = parent[root]
        while parent[node] != node:
            next_node = parent[node]
            parent[node] = root
            node = next_node
        return root

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    edges = []
    for position, edge in enumerate(case["distances"]):
        left, right, distance = edge
        weight = max(distance, core_distance[left], core_distance[right])
        edges.append((weight, position, left, right))

    edges.sort(key=lambda edge: (edge[0], edge[1]))
    mst_edges = []
    total_weight = 0.0
    for weight, _, left, right in edges:
        if union(left, right):
            mst_edges.append([left, right, weight])
            total_weight += weight
            if len(mst_edges) == max(0, len(nodes) - 1):
                break

    return {"mst_edges": mst_edges, "total_weight": round(total_weight, 8)}"}
